package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import com.ruoyi.paiflow.domain.RunRecord;
import com.ruoyi.paiflow.mapper.*;
import java.nio.file.*;
import java.sql.*;
import java.time.*;
import java.util.*;
import org.h2.jdbcx.JdbcDataSource;
import org.apache.ibatis.builder.xml.XMLMapperBuilder;
import org.apache.ibatis.mapping.Environment;
import org.apache.ibatis.session.*;
import org.mybatis.spring.*;
import org.mybatis.spring.transaction.SpringManagedTransactionFactory;
import org.springframework.aop.framework.ProxyFactory;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.annotation.AnnotationTransactionAttributeSource;
import org.springframework.transaction.interceptor.TransactionInterceptor;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** 真实变量Mapper/事务与中心当时回执；租约/会话端口隔离，不是真实MySQL验收。 */
public class RunVariableSourceTest {
    JdbcDataSource db;Connection schema;RunVariableMapper rows;RunVariableService service,target;CompletedOutputSources sources;RunRecord run;JSONObject node,task,context;RunMapper events;RunLeaseService leases;RunHistoryService histories;
    WorkerIdentityService.Principal worker=new WorkerIdentityService.Principal("worker","python");
    public static Timestamp utcNow(int precision){return Timestamp.from(Instant.now());}
    private <T> T tx(T value){var p=new ProxyFactory(value);p.setProxyTargetClass(true);p.addAdvice(new TransactionInterceptor(new DataSourceTransactionManager(db),new AnnotationTransactionAttributeSource()));return (T)p.getProxy();}
    private static <T> ObjectProvider<T> provider(T value){ObjectProvider<T> p=mock(ObjectProvider.class);when(p.getIfAvailable()).thenReturn(value);return p;}
    @BeforeEach void setup() throws Exception {
        db=new JdbcDataSource();db.setURL("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1");schema=db.getConnection();try(var sql=schema.createStatement()){sql.execute("CREATE ALIAS UTC_TIMESTAMP FOR 'com.ruoyi.paiflow.service.RunVariableSourceTest.utcNow'");sql.execute("CREATE TABLE paiflow_run(id VARCHAR(36) PRIMARY KEY)");sql.execute("INSERT INTO paiflow_run VALUES('run-variable')");for(String name:List.of("022-paiflow-runtime-variable.sql","032-paiflow-variable-source-snapshot.sql")){String ddl=Files.readString(Path.of("sql",name)).replaceAll("(?m)^--.*$","").replace(" CHARACTER SET ascii COLLATE ascii_bin","").replace(" ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin","").replace(" ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","");for(String statement:ddl.split(";"))if(!statement.isBlank())sql.execute(statement);}}
        var config=new Configuration(new Environment("private-variable",new SpringManagedTransactionFactory(),db));String xml=new String(getClass().getResourceAsStream("/mapper/paiflow/RunVariableMapper.xml").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).replace("IF(expires_at&gt;UTC_TIMESTAMP(3),values_json,'{}')","CASE WHEN expires_at&gt;UTC_TIMESTAMP(3) THEN values_json ELSE '{}' END").replace("UTC_TIMESTAMP(3)+INTERVAL 7 DAY","DATEADD('DAY',7,UTC_TIMESTAMP(3))");new XMLMapperBuilder(new java.io.StringReader(xml),config,"variables",config.getSqlFragments()).parse();rows=new SqlSessionTemplate(new SqlSessionFactoryBuilder().build(config)).getMapper(RunVariableMapper.class);
        run=new RunRecord();run.setId("run-variable");run.setLeaseId("lease");run.setAttempt(1);run.setState("RUNNING");run.setExecutionStartedAt(LocalDateTime.now());run.setSpaceId(1L);run.setWorkflowId(2L);run.setOwnerUserId(42L);run.setLastEventSeq(0L);
        var field=JSONObject.of("name","value","schema",JSONObject.of("type","integer","value",JSONObject.of("type","ref","content",JSONObject.of("nodeId","node-start::s","name","value"))));node=JSONObject.of("id","node-variable::v","data",JSONObject.of("nodeParam",JSONObject.of("method","set"),"inputs",new JSONArray(List.of(field)),"outputs",new JSONArray(List.of(JSONObject.of("name","value","schema",JSONObject.of("type","integer","default",-1)),JSONObject.of("name","fallback","schema",JSONObject.of("type","boolean","default",false))))));task=JSONObject.of("dsl",JSONObject.of("nodes",new JSONArray(List.of(JSONObject.of("id","node-start::s","data",JSONObject.of("outputs",new JSONArray())),node)),"edges",new JSONArray()),"input",JSONObject.of("value",0),"effectPolicy",JSONObject.of("mode","approved_write","allowedOperations",new JSONArray(List.of("variables.set"))));run.setAssignmentJson(task.toJSONString());context=JSONObject.of("appId","app","chatId","chat");events=mock(RunMapper.class);when(events.eventsThrough(anyString(),anyLong(),anyLong(),anyInt())).thenReturn(List.of());leases=mock(RunLeaseService.class);when(leases.requireActiveLease(run.getId(),worker,"lease",1)).thenReturn(run);histories=mock(RunHistoryService.class);when(histories.executionContext(run)).thenAnswer(x->context);sources=new CompletedOutputSources(null,null,null);target=new RunVariableService(rows,leases,histories);target.useSources(provider(sources),events);service=tx(target);
    }
    @AfterEach void close() throws Exception {schema.close();}
    JSONObject request(String operation){return JSONObject.of("leaseId","lease","attempt",1,"nodeId",node.get("id"),"operation",operation);}
    JSONObject set(Object value,String key,long revision){var req=request("set");req.putAll(JSONObject.of("variableName","value","value",value,"expectedRevision",revision,"idempotencyKey",key));return req;}
    void getNode(){node.getJSONObject("data").getJSONObject("nodeParam").put("method","get");run.setAssignmentJson(task.toJSONString());}
    @Test void actualWriteReceiptDefaultAndReplayPreserveFalseZero(){var req=set(0,"natural_write",0);var result=service.operate(run.getId(),worker,req);assertEquals(1,result.getLongValue("revision"));assertTrue(ToolSchema.same(result,service.operate(run.getId(),worker,req)));assertEquals(JSONObject.of("value",0,"fallback",false),service.completed(run,node));assertEquals(1,rows.snapshots(run.getId(),"lease",1,node.getString("id")).size());}
    @Test void forgedValueCannotWriteOrRecord(){assertEquals(409,assertThrows(com.ruoyi.common.exception.ServiceException.class,()->service.operate(run.getId(),worker,set(9,"forged",0))).getCode());assertTrue(rows.snapshots(run.getId(),"lease",1,node.getString("id")).isEmpty());}
    @Test void currentStateCannotReplaceActualReadSnapshot() throws Exception {getNode();String scope=RunJsonBoundary.hashFull(JSONObject.of("space",1,"workflow",2,"owner",42,"app","app","chat","chat"));assertEquals(1,rows.initialize(scope));try(var sql=schema.createStatement()){sql.execute("UPDATE paiflow_runtime_variable SET values_json='{\"value\":0}',expires_at=TIMESTAMP '2099-01-01 00:00:00' WHERE scope_key='"+scope+"'");}var response=service.operate(run.getId(),worker,request("get_all"));try(var sql=schema.createStatement()){sql.execute("UPDATE paiflow_runtime_variable SET values_json='{\"value\":999}',revision=1 WHERE scope_key='"+scope+"'");}assertTrue(ToolSchema.same(response,service.operate(run.getId(),worker,request("get_all"))));assertEquals(0,service.completed(run,node).getIntValue("value"));}
    @Test void failedSnapshotInsertRollsBackStateAndIdempotentReceipt(){var failing=spy(rows);doThrow(new IllegalStateException("isolated snapshot failure")).when(failing).recordSnapshot(anyString(),anyString(),anyInt(),anyString(),anyString(),anyString(),anyString(),anyString(),anyString(),anyString(),anyString());var t=new RunVariableService(failing,leases,histories);t.useSources(provider(sources),events);assertThrows(IllegalStateException.class,()->tx(t).operate(run.getId(),worker,set(0,"rollback",0)));assertNull(rows.request(run.getId(),1,ModelOperationJson.sha("rollback")));assertEquals(1,service.operate(run.getId(),worker,set(0,"retry",0)).getLongValue("revision"));}
    @Test void currentVariableReceiptThenCommonSourceAllowsExactEventAndRejectsForgery(){getNode();service.operate(run.getId(),worker,request("get_all"));var consumer=JSONObject.of("id","plugin::consumer","data",JSONObject.of("inputs",new JSONArray(List.of(JSONObject.of("name","answer","schema",JSONObject.of("type","integer","value",JSONObject.of("type","ref","content",JSONObject.of("nodeId",node.get("id"),"name","value"))))))));task.getJSONObject("dsl").getJSONArray("nodes").add(consumer);task.getJSONObject("dsl").put("edges",new JSONArray(List.of(JSONObject.of("sourceNodeId",node.get("id"),"targetNodeId",consumer.get("id")))));run.setAssignmentJson(task.toJSONString());var event=JSONObject.of("runId",run.getId(),"leaseId",run.getLeaseId(),"attempt",run.getAttempt(),"seq",1,"nodeId",node.get("id"),"eventType","node.completed","payload",JSONObject.of("legacyFrame",JSONObject.of("workflow_step",JSONObject.of("node",JSONObject.of("id",node.get("id"),"outputs",JSONObject.of("value",0,"fallback",false))))));run.setLastEventSeq(1L);when(events.eventsThrough(anyString(),anyLong(),anyLong(),anyInt())).thenReturn(List.of(new RunMapper.EventRow(1,event.toJSONString())));sources.useVariableSources(provider(service));sources.verify(run,task.getJSONObject("dsl"),consumer,new JSONArray(List.of(event)));event.getJSONObject("payload").getJSONObject("legacyFrame").getJSONObject("workflow_step").getJSONObject("node").getJSONObject("outputs").put("value",123);assertEquals(409,assertThrows(com.ruoyi.common.exception.ServiceException.class,()->sources.verify(run,task.getJSONObject("dsl"),consumer,new JSONArray(List.of(event)))).getCode());}
    @Test void otherSessionOrLeaseAndTamperedSnapshotCannotAuthorize() throws Exception {getNode();service.operate(run.getId(),worker,request("get_all"));context=JSONObject.of("appId","other","chatId","chat");assertThrows(com.ruoyi.common.exception.ServiceException.class,()->service.completed(run,node));context=JSONObject.of("appId","app","chatId","chat");run.setLeaseId("different");assertThrows(com.ruoyi.common.exception.ServiceException.class,()->service.completed(run,node));run.setLeaseId("lease");try(var sql=schema.createStatement()){sql.execute("UPDATE paiflow_variable_source SET response_json='{\"variables\":{\"value\":55}}'");}assertThrows(com.ruoyi.common.exception.ServiceException.class,()->service.completed(run,node));}
}
